mapper.select:
SELECT c.id, c.course_name, c.description, c.course_type, c.semester, c.location, c.teacher_id, t.real_name as teacher_name, u.avatar as teacher_avatar, c.cover_image_url, c.status, c.is_public, c.create_time, c.update_time FROM mg_course c LEFT JOIN mg_teacher t ON c.teacher_id = t.id LEFT JOIN sys_user u ON t.sys_user_id = u.id INNER JOIN mg_course_assistant_teacher at ON c.id = at.course_id
c.is_deleted = 0 AND t.is_deleted = 0 AND at.assistant_teacher_id = #{teacherId}
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
AND c.status = #{status}
AND c.is_public = #{isPublic}
AND c.create_time >= #{startTime}
AND c.create_time <= #{endTime}
ORDER BY c.create_time DESC

mapper.delete:
DELETE FROM mg_course_assistant_teacher
WHERE course_id = #{courseId}
AND assistant_teacher_id IN

    #{id}

mapper.select:
SELECT assistant_teacher_id FROM mg_course_assistant_teacher
WHERE course_id = #{courseId}
ORDER BY create_time DESC

SELECT t.id, t.teacher_code, t.real_name, t.birth_date, t.department, t.education, t.specialization, t.description, t.sys_user_id, u.avatar, u.username, u.nick_name, u.email, u.mobile, t.create_time, t.update_time, u.last_login_time FROM mg_teacher t LEFT JOIN sys_user u ON t.sys_user_id = u.id INNER JOIN mg_course_assistant_teacher at ON t.id = at.assistant_teacher_id
t.is_deleted = 0 AND at.course_id = #{courseId}
ORDER BY at.create_time DESC
